package com.example;import org.slf4j.*;import org.springframework.cache.annotation.Cacheable;import org.springframework.stereotype.Service;@Service public class ProductService {private static final Logger log=LoggerFactory.getLogger(ProductService.class);private final ProductRepository repo;public ProductService(ProductRepository r){repo=r;}@Cacheable("products") public Product getProduct(Long id){log.info("Fetching product {} from database",id);return repo.findById(id).orElseThrow();}}
